BEGIN
 SELECT p.prosrc INTO guard_source FROM pg_proc p
  WHERE p.oid='secureshop_agents.guard_bound_tool_registry_upgrade()'::regprocedure;
 IF guard_source IS NULL OR encode(sha256(convert_to(guard_source,'UTF8')),'hex')<>old_guard_sha256
  OR position(old_edge IN guard_source)=0 OR position(v28_branch IN guard_source)=0
  OR position(denial_anchor IN guard_source)=0 THEN
  RAISE EXCEPTION 'Expected v28 product search registry guard is unavailable' USING ERRCODE='55000';
 END IF;
 guard_source:=replace(guard_source,old_edge,old_edge||E'\n'||new_edges);
 guard_source:=replace(guard_source,v28_branch,v29_branch||v28_branch);
 guard_source:=replace(guard_source,denial_anchor,E'\n END IF;'||denial_anchor);
 IF encode(sha256(convert_to(guard_source,'UTF8')),'hex')<>upgraded_guard_sha256 THEN
  RAISE EXCEPTION 'Product search registry guard checksum mismatch' USING ERRCODE='55000';
 END IF;
 EXECUTE format('CREATE OR REPLACE FUNCTION secureshop_agents.guard_bound_tool_registry_upgrade() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,secureshop_agents AS %L',guard_source);
 SELECT pg_get_constraintdef(c.oid) INTO constraint_def FROM pg_constraint c
